   print *, "PRROC R-reference assertions:", checks
contains
   subroutine close_scalar(actual, expected, checks)
      real(dp), intent(in) :: actual !! Scalar produced by the Fortran implementation.
      real(dp), intent(in) :: expected !! Numeric oracle from preserved PRROC 1.4 R source.
      integer, intent(inout) :: checks !! Running number of successful numeric assertions.
      if (ieee_is_nan(actual) .or. abs(actual - expected) > 2.0e-12_dp) then
         print *, "Scalar mismatch:", actual, expected
         error stop "R scalar oracle"
      end if
      checks = checks + 1
   end subroutine close_scalar
   subroutine close_curve(actual, expected, checks)
      real(dp), intent(in) :: actual(:,:) !! Observed Fortran curve matrix with three columns.
      real(dp), intent(in) :: expected(:,:) !! Upstream matrix with unused all-NA padding removed.
      integer, intent(inout) :: checks !! Running number of successful matrix assertions.
      if (any(shape(actual) /= shape(expected))) then
         print *, "Curve shape mismatch:", shape(actual), shape(expected)
         error stop "R curve shape"
      end if
      if (any(ieee_is_nan(actual)) .or. any(abs(actual - expected) > 3.0e-12_dp)) then
         print *, "Curve max error:", maxval(abs(actual - expected))
         error stop "R curve oracle"
      end if
      checks = checks + 1
   end subroutine close_curve
end program test_r_reference
